const workflowContext = this;
const env = $env || {};

function required(value, name) {
  if (value === undefined || value === null || String(value).trim() === '') {
    throw new Error(`${name} is required`);
  }
  return value;
}

function trimSlash(value) {
  return String(value || '').replace(/\/+$/, '');
}

function safeString(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function parseList(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.filter(Boolean);
  return String(value)
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean);
}

function extractPayload(description) {
  const text = String(description || '');
  const m = text.match(/<!--HR_TALENT_SKILL_UPDATE_JSON:([\s\S]*?)-->/);
  if (!m) return null;
  try {
    return JSON.parse(m[1]);
  } catch (error) {
    return null;
  }
}

function hasApprovalMarker(text) {
  const t = String(text || '').trim();
  if (!t) return false;
  const lower = t.toLowerCase();
  if (lower.startsWith('/approve')) return true;
  if (lower.startsWith('[approve]')) return true;
  if (lower.startsWith('approve:')) return true;
  if (lower.startsWith('承認')) return true;
  return false;
}

function yamlEscape(value) {
  const raw = value === undefined || value === null ? '' : String(value);
  const cleaned = raw.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const needsQuote = /[:#\n\t\-\{\}\[\],&\*\?\|<>=!%@`]/.test(cleaned) || cleaned.trim() !== cleaned;
  const safe = cleaned.replace(/"/g, '\\"');
  return needsQuote ? `"${safe}"` : safe;
}

const realm = safeString(env.N8N_REALM || env.N8N_OBSERVER_REALM || 'default') || 'default';

const gitlabBaseUrl = trimSlash(env.N8N_GITLAB_BASE_URL || env.GITLAB_BASE_URL || env.GITLAB_URL || env.SERVICE_URL_GITLAB || '');
const gitlabApiBase = trimSlash(env.N8N_GITLAB_API_BASE_URL || env.GITLAB_API_BASE_URL || (gitlabBaseUrl ? `${gitlabBaseUrl}/api/v4` : '') || '');
const gitlabToken = safeString(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '');

function normalizeProjectRef(value) {
  const v = safeString(value);
  if (!v) return '';
  if (/^\d+$/.test(v)) return v;
  if (v.includes('/')) return v;
  return `${realm}/${v}`;
}

let projectRefRaw = safeString(env.HR_TALENT_GITLAB_PROJECT_ID || env.HR_TALENT_GITLAB_PROJECT_PATH || env.N8N_GITLAB_PROJECT_ID || env.N8N_GITLAB_PROJECT_PATH || '' || env.HR_TALENT_PROJECT_PATH || env.HR_TALENT_MANAGEMENT_PROJECT_PATH || '');
let projectRef = normalizeProjectRef(projectRefRaw);
if (!projectRef) {
  projectRef = `${realm}/hr-talent-management`;
}

const defaultBranch = safeString(env.HR_TALENT_DEFAULT_BRANCH || 'main') || 'main';
const approveLabels = parseList(env.HR_TALENT_APPROVE_LABELS || 'status:approved');

required(gitlabApiBase, 'GITLAB_API_BASE_URL');
required(gitlabToken, 'GITLAB_TOKEN');
required(projectRef, 'HR_TALENT_GITLAB_PROJECT_ID or HR_TALENT_GITLAB_PROJECT_PATH (or HR_TALENT_PROJECT_PATH)');

const zulipBaseUrl = trimSlash(env.ZULIP_API_BASE_URL || env.N8N_ZULIP_API_BASE_URL || '');
const zulipEmail = safeString(env.ZULIP_BOT_EMAIL || env.ZULIP_EMAIL || '');
const zulipApiKey = safeString(env.ZULIP_BOT_API_KEY || env.ZULIP_API_KEY || '');
const zulipStream = safeString(env.HR_TALENT_ZULIP_STREAM || '');
const zulipTopicDefault = safeString(env.HR_TALENT_ZULIP_TOPIC || 'hr-talent') || 'hr-talent';

async function zulipSendStreamMessage(content, topic) {
  if (!zulipBaseUrl || !zulipEmail || !zulipApiKey || !zulipStream) return null;
  const url = `${zulipBaseUrl}/api/v1/messages`;
  const auth = Buffer.from(`${zulipEmail}:${zulipApiKey}`).toString('base64');
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: {
      'Authorization': `Basic ${auth}`,
    },
    form: {
      type: 'stream',
      to: zulipStream,
      topic: topic || zulipTopicDefault,
      content,
    }
  });
}


const projectEncoded = encodeURIComponent(projectRef);

async function listIssues() {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/issues`;
  return await workflowContext.helpers.httpRequest({
    method: 'GET',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    qs: {
      state: 'opened',
      labels: 'hr-skill-update,status:pending-approval',
      per_page: 100,
      order_by: 'updated_at',
      sort: 'asc'
    }
  });
}

async function listNotes(iid) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/issues/${iid}/notes`;
  return await workflowContext.helpers.httpRequest({
    method: 'GET',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    qs: {
      per_page: 100,
      order_by: 'created_at',
      sort: 'asc'
    }
  });
}

async function createBranch(branch) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/branches`;
  try {
    return await workflowContext.helpers.httpRequest({
      method: 'POST',
      url,
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken },
      qs: { branch, ref: defaultBranch }
    });
  } catch (err) {
    const status = err?.response?.statusCode || err?.statusCode || null;
    // 400/409: already exists
    if (status === 400 || status === 409) return null;
    throw err;
  }
}

async function fileExists(filePath, ref) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/files/${encodeURIComponent(filePath)}`;
  try {
    await workflowContext.helpers.httpRequest({
      method: 'GET',
      url,
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken },
      qs: { ref }
    });
    return true;
  } catch (err) {
    const status = err?.response?.statusCode || err?.statusCode || null;
    if (status === 404) return false;
    return false;
  }
}

async function createCommit(branch, filePath, content, commitMessage) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/commits`;
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: {
      branch,
      commit_message: commitMessage,
      actions: [
        {
          action: 'create',
          file_path: filePath,
          content,
        }
      ]
    }
  });
}

async function createMr(sourceBranch, title, description) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/merge_requests`;
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: {
      source_branch: sourceBranch,
      target_branch: defaultBranch,
      title,
      description,
      remove_source_branch: true,
    }
  });
}

async function postNote(iid, note) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/issues/${iid}/notes`;
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: { body: note }
  });
}

async function setLabels(iid, labels) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/issues/${iid}`;
  return await workflowContext.helpers.httpRequest({
    method: 'PUT',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: { labels: labels.join(',') }
  });
}

let issues;
try {
  issues = await listIssues();
} catch (err) {
  const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
  const responseBody = err?.response?.body || err?.response?.data || null;
  return [{
    json: {
      ok: false,
      status_code: status || 500,
      error: String(err?.message || err),
      response_body: responseBody,
      realm,
      project_ref: projectRef,
    }
  }];
}

const applied = [];
const skipped = [];
const errors = [];

for (const issue of (Array.isArray(issues) ? issues : [])) {
  const iid = issue?.iid;
  if (!iid) continue;

  const labels = Array.isArray(issue.labels) ? issue.labels : [];
  if (labels.includes('status:applied') || labels.includes('hr-talent:applied')) {
    skipped.push({ iid, reason: 'already_applied' });
    continue;
  }

  let notes;
  try {
    notes = await listNotes(iid);
  } catch (err) {
    errors.push({ iid, step: 'list_notes', error: String(err?.message || err) });
    continue;
  }

  const approvedByLabel = approveLabels.some((l) => labels.includes(l));
  const approvedByNote = Array.isArray(notes) ? notes.some((n) => !n?.system && hasApprovalMarker(n?.body)) : false;

  if (!approvedByLabel && !approvedByNote) {
    skipped.push({ iid, reason: 'not_approved' });
    continue;
  }

  const payload = extractPayload(issue.description);
  if (!payload || !payload.person_key || !payload.skill_id || !payload.level) {
    skipped.push({ iid, reason: 'missing_payload' });
    continue;
  }

  const branch = `hr-skill-update-${iid}`;
  const filePath = `ledger/skill_updates/skill_update_${iid}.yml`;

  try {
    await createBranch(branch);

    const exists = await fileExists(filePath, branch);
    if (!exists) {
      const now = new Date().toISOString();
      const yaml = [
        'kind: skill_update',
        `realm: ${yamlEscape(payload.realm || realm)}`,
        `requested_at: ${yamlEscape(payload.requested_at || now)}`,
        `requested_by: ${yamlEscape(payload.requested_by || '')}`,
        `person_key: ${yamlEscape(payload.person_key)}`,
        `skill_id: ${yamlEscape(payload.skill_id)}`,
        `level: ${yamlEscape(payload.level)}`,
        payload.evidence ? `evidence: ${yamlEscape(payload.evidence)}` : null,
        payload.notes ? `notes: ${yamlEscape(payload.notes)}` : null,
        'source:',
        `  gitlab_issue_iid: ${iid}`,
        `  gitlab_issue_url: ${yamlEscape(issue.web_url || '')}`,
      ].filter((v) => v !== null).join('\n') + '\n';

      await createCommit(
        branch,
        filePath,
        yaml,
        `Apply skill update from issue #${iid}`
      );
    }

    const mr = await createMr(
      branch,
      `Apply skill update: ${payload.person_key} ${payload.skill_id} -> ${payload.level} (#${iid})`,
      `This MR was generated by n8n (hr-talent-skill-update-apply-cron).\n\nSource issue: ${issue.web_url || ''}`
    );

    const appliedMarker = '<!--HR_TALENT_APPLIED-->';
    const noteBody = [
      appliedMarker,
      'スキル更新が承認されたため、台帳更新のMRを作成しました。',
      mr?.web_url ? `MR: ${mr.web_url}` : null,
    ].filter((v) => v !== null).join('\n');

    await postNote(iid, noteBody);

    const newLabels = Array.from(new Set([
      ...labels.filter((l) => l !== 'status:pending-approval'),
      'status:applied',
      'hr-talent:applied',
    ]));

    await setLabels(iid, newLabels);


    try {
      const msg = [
        'HR Talent: スキル更新が反映されました。',
        `- realm: ${realm}`,
        `- person_key: ${payload.person_key}`,
        `- skill_id: ${payload.skill_id}`,
        `- level: ${payload.level}`,
        issue?.web_url ? `- issue: ${issue.web_url}` : null,
        mr?.web_url ? `- mr: ${mr.web_url}` : null,
      ].filter((v) => v !== null).join('\n');
      await zulipSendStreamMessage(msg, 'hr-skill-update-applied');
    } catch (err) {
      // ignore zulip failures
    }

applied.push({ iid, mr_url: mr?.web_url || null, file_path: filePath });
  } catch (err) {
    const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
    const responseBody = err?.response?.body || err?.response?.data || null;
    errors.push({
      iid,
      step: 'apply',
      status_code: status || null,
      error: String(err?.message || err),
      response_body: responseBody,
    });
  }
}

return [{
  json: {
    ok: true,
    status_code: 200,
    realm,
    project_ref: projectRef,
    counts: {
      scanned: Array.isArray(issues) ? issues.length : 0,
      applied: applied.length,
      skipped: skipped.length,
      errors: errors.length,
    },
    applied,
    skipped,
    errors,
  }
}];
